import * as K from './economy.js';
import * as B from './studio-growth.js';
import * as Vault from './save-vault.js';
import {GENRE,ROLE_NAMES} from './data.js';
import {runtimeOf} from './runtime.js';

/** Expansion UI uses existing dialog/back stack; callbacks and import candidates stay
 * outside ui so they cannot leak into History API structured-clone data. */
export function createGrowthFeatures(ctx){
 const {ui,E,esc,btn,icon,avatar,dialogFrame,pageHead,render,renderDialog,persist,toast,features}=ctx;
 const state=()=>ctx.getGame(),group=()=>B.initGrowth(state()),film=id=>state()?.films.find(f=>f.id===id);
 let slots=[],vaultError='',loadingVault=false,pendingImport=null,autoTimer=null,confirmationCounter=0;
 const confirmations=new Map();
 const A=(label,type,id='',cls='ghost small-btn',extra='')=>btn(label,'growth-'+type,`data-id="${esc(id)}" ${extra}`,cls);
 const back=()=>btn('뒤로가기','close','','ghost');
 const shell=(title,subtitle,body,footer='')=>dialogFrame(title,subtitle,body,footer||back());
 const safeDate=w=>E.weekDate(Number.isFinite(w)?w:0);
 const m=n=>E.money(Number(n)||0);
 const signed=n=>(n>=0?'+':'')+m(n);
 const ownFilms=()=>state()?.films.filter(f=>f.company==='c0')??[];
 const blank=(title,text)=>`<div class="card empty"><h3>${title}</h3><p>${text}</p></div>`;
 function show(type,id){ui.growthPage=0;features.deepOpen('growth-'+type,id);if(type==='storage')loadSlots();}
 function ask(title,text,run,label='확정',detail=''){
  const id=String(++confirmationCounter);confirmations.set(id,{title,text,run,label,detail,returnTo:ui.modal?{...ui.modal}:null});
  if(confirmations.size>20)confirmations.delete(confirmations.keys().next().value);
  features.deepOpen('growth-confirm',id);
 }
 async function asyncRun(fn){if(ui.growthBusy)return;ui.growthBusy=true;try{await fn();}catch(e){toast(e.message||'작업하지 못했습니다.',true);}finally{ui.growthBusy=false;}}
 async function loadSlots(){
  loadingVault=true;try{slots=await Vault.listSaves();vaultError='';}catch(e){vaultError=e.message;}finally{loadingVault=false;if(ui.modal?.type==='growth-storage')renderDialog();}
 }
 function toolbar(view){
  const routes={studio:[['기획 보관함','drafts'],['저장한 제작팀','teams'],['시설 관리','facilities']],finance:[['투자·공동제작','investment'],['해외 정산','foreign-report']],portfolio:[['시리즈·세계관','series']],awards:[['영화제 출품','festivals']],market:[['해외 성과','foreign-report']]};
  const items=routes[view]??[];return items.length?`<nav class="growth-toolbar" aria-label="확장 기능">${items.map(([l,t])=>A(l,t)).join('')}</nav>`:'';
 }
 function favoriteControl(p){if(!state()||!p)return '';const on=group().favorites.includes(p.id);return btn(`${on?'★ 관심 해제':'☆ 관심 인물'}`,'growth-favorite',`data-id="${esc(p.id)}" aria-pressed="${on}"`,'ghost small-btn');}
 function wrapPerson(p,html,picker=false){if(picker||!state())return html;const on=group().favorites.includes(p.id);return `<div class="growth-person-tile">${html}<button class="growth-favorite-pin ${on?'is-favorite':''}" data-action="growth-favorite" data-id="${p.id}" aria-label="${esc(p.name)} ${on?'관심 해제':'관심 등록'}" aria-pressed="${on}">${on?'★':'☆'}</button></div>`;}
 function favoritesButton(){return A(`★ 관심 ${group()?.favorites.length??0}`,'favorites');}
 function personLink(id,label=''){const p=E.person(state(),id);return p?`<button class="growth-person-link" data-action="person-peek" data-id="${esc(id)}">${avatar(p)}<span><strong>${esc(p.name)}</strong><small>${esc(label||ROLE_NAMES[p.role])} · ${p.status==='retired'?'은퇴':p.status==='dead'?'기록 보존':E.busyFilm(state(),id)?'촬영 중':'일정 확인 가능'}</small></span>${icon('chevron')}</button>`:'<span class="muted">이전 인물</span>';}
 function filmRow(f,action,label='선택'){return `<article class="growth-film-row"><button class="growth-poster" data-action="film-peek" data-id="${f.id}" aria-label="${esc(f.title)} 상세">${features.posterArt(f)}</button><div><strong>${esc(f.title)}</strong><small>${ctx.statusLabel(f)} · ${runtimeOf(f)}분 · ${m(f.spent)}</small></div>${A(label,action,f.id)}</article>`;}
 function favoritesView(){
  const all=group().favorites.map(id=>E.person(state(),id)).filter(Boolean),size=12,pages=Math.max(1,Math.ceil(all.length/size)),page=Math.min(ui.growthPage??0,pages-1);
  return shell('관심 인물','즐겨 찾는 감독·배우·작가를 모았습니다. 등록 당시 ID를 보존하므로 세대가 바뀌어도 다른 사람으로 바뀌지 않습니다.',`<div class="growth-people-list">${all.slice(page*size,(page+1)*size).map(p=>`<article class="card">${personLink(p.id)}${favoriteControl(p)}</article>`).join('')||blank('관심 인물이 없습니다.','인물 카드의 별표 또는 상세정보의 관심 인물 버튼으로 등록하세요.')}</div>${pages>1?pager(page,pages):''}`);
 }
 function pager(page,pages){return `<div class="pagination">${A('이전','page','','ghost small-btn',`data-delta="-1" ${page===0?'disabled':''}`)}<span>${page+1} / ${pages}</span>${A('다음','page','','ghost small-btn',`data-delta="1" ${page+1>=pages?'disabled':''}`)}</div>`;}
 function teamView(){
  const teams=group().teams;
  return shell('저장한 제작팀','감독·주연·조연 조합을 최대 12개 보관합니다. 불러올 때 일정·활동 상태를 재검사하며 작가는 현재 시나리오에 따릅니다.',`<div class="growth-save-team"><label for="growth-team-name">팀 이름</label><input id="growth-team-name" maxlength="32" placeholder="예: 우리 회사 드라마 팀" value="${esc(ui.growthTeamName??'')}" data-growth="teamName">${A('현재 기획의 제작팀 저장','team-save','','primary',ui.draft?'':'disabled')}</div>${teams.map(t=>`<section class="card growth-card"><div class="row between"><h3>${esc(t.name)}</h3>${A('삭제','remove',t.id,'text-btn','data-kind="teams"')}</div><div class="growth-team-members">${[t.director,...t.leads,...t.supports].map(id=>personLink(id)).join('')}</div>${A('현재 기획에 불러오기','team-load',t.id,'primary',ui.draft?'':'disabled')}</section>`).join('')||blank('저장한 제작팀이 없습니다.','영화 기획에서 제작진을 모두 선택한 뒤 저장하세요.')}<p class="small muted">선택만으로 계약하지 않습니다. 불러온 후 최종 섭외에서 전체 관계와 추가 개런티를 다시 확인합니다.</p>`);
 }
 function draftsView(){
  const drafts=group().drafts;
  return shell('기획 보관함','자동 초안 1개와 직접 저장 8개. 새 시나리오로 바꾸기 전 자동 초안도 덮어쓰기 전에 별도 보관하세요.',`${ui.draft?`<section class="card growth-card"><h3>현재 기획 · ${esc(ui.draft.title)}</h3>${A('이 기획을 별도로 저장','draft-save','','primary')}</section>`:''}${drafts.map(d=>`<article class="card growth-card"><div class="row between"><h3>${esc(d.title)}</h3><span class="tag outline">${d.id==='auto-draft'?'자동 초안':'직접 저장'}</span></div><p class="small muted">${safeDate(d.week)} · ${['작품 기획','캐스팅','제작 확정'][d.step]} · ${d.draft.genres.map(g=>GENRE[g]?.name??g).map(esc).join(' / ')}</p><p class="growth-clamp small">${esc(d.draft.script.synopsis)}</p><div class="row wrap">${A('이어서 편집','draft-load',d.id,'primary')}${A('삭제','remove',d.id,'ghost small-btn','data-kind="drafts"')}</div></article>`).join('')||blank('보관 중인 기획이 없습니다.','기획을 시작하면 자동 초안을 보관합니다. 창을 닫아도 기획을 다시 열 수 있습니다.')}`);
 }
 function facilityView(){
  return shell('시설 관리','촬영·후반작업 기반을 확장합니다. 효과는 새 계약 시점에 고정되며 기존 영화에 소급 적용되지 않습니다.',`<div class="notice"><p>월 시설비 <strong>${m(B.facilityMonthlyCost(state()))}</strong> · 월 운영비와 함께 4주마다 정산. 임대는 개시비와 월 임대료, 보유는 구입비와 월 유지비가 듭니다.</p></div><div class="growth-cards">${B.FACILITIES.map(f=>{const own=group().facilities[f.id];return `<section class="card growth-card"><div class="row between"><h3>${f.name}</h3><span class="tag ${own?'green':'outline'}">${own?.mode==='own'?'보유':own?'임대 중':'미운영'}</span></div><p>${f.description}</p><dl class="growth-values"><div><dt>구입 / 월 유지</dt><dd>${m(f.purchase)} / ${m(f.maintenance)}</dd></div><div><dt>임대 개시 / 월 임대</dt><dd>${m(f.setup)} / ${m(f.rent)}</dd></div></dl><div class="row wrap">${own?.mode!=='own'?A('구입','facility',f.id,'primary','data-mode="own"'):''}${!own?A('임대','facility',f.id,'ghost','data-mode="lease"'):''}${own?A(own.mode==='own'?'처분 (구입가 40%)':'임대 종료','facility',f.id,'ghost','data-mode="remove"'):''}</div></section>`;}).join('')}</div><p class="small muted">촬영 준비비 할인은 배우 계약료·원작 선급금에 적용하지 않습니다. 3개 시설의 최대 효과는 준비비 11% 절감·4주 단축이며, 구입가와 처분가는 게임 설정입니다.</p>`);
 }
 function investmentView(){
  const d=ui.draft,estimate=d?E.estimate(d,state()):null,offers=d?B.investorOffers(state(),d,estimate):[];
  return shell('투자·공동제작','비용을 먼저 회수한 뒤 순이익을 배분합니다. 외부 투자금의 회수는 실제 투자액 한도이며 대출처럼 상환을 보장하지 않습니다.',`${d?`<div class="notice"><p><strong>${esc(d.title)}</strong><br>총 제작비 ${m(estimate.total)} · 선정 투자금 ${m(estimate.finance?.eligible?estimate.finance.amount:0)} · 필요한 우리 자금 <strong>${m(estimate.cashNeeded)}</strong></p></div><div class="growth-cards">${offers.map(o=>`<section class="card growth-card ${d.investorId===o.id?'is-selected':''}"><h3>${o.name}</h3><div class="growth-big-value">${m(o.amount)} <small>제작비 ${Math.round(o.funding*100)}%</small></div><p>${o.rule}</p><p class="small">비용 회수 중: 실제 투자금 비례 회수<br>회수 후 순이익: 투자사 ${Math.round(o.share*100)}% · 우리 회사 ${Math.round((1-o.share)*100)}%<br>공개 기한 ${safeDate(o.deadline)}</p>${o.issues.length?`<div class="notice warning small">${o.issues.map(esc).join(' · ')}</div>`:''}${A(d.investorId===o.id?'선택됨':'이 조건으로 선택','investor-select',o.id,'primary',o.eligible?'':'disabled')}</section>`).join('')}</div>${A('투자 없이 자체 제작','investor-select','','ghost mt-sm')}<p class="small muted">선택 단계에서는 돈이 오가지 않습니다. 캐스팅·규모·기간이 바뀌면 제작 확정 시 재계산합니다. 공개 기한을 넘기면 비용 회수 후 투자사 순이익 몫이 5%p 한 번 증가합니다. 추가 이자·일괄 현금 벌금은 없습니다. 국내·OTT·해외 정산 모두 배분 대상입니다.</p>`:blank('기획 중인 작품을 선택하세요.','시나리오를 기획한 뒤 이 화면에서 제안을 비교할 수 있습니다.')}
   <h3 class="mt">체결된 공동제작 계약</h3>${ownFilms().filter(f=>f.investment).map(f=>`<section class="card growth-card"><h3>${esc(f.title)} · ${esc(f.investment.name)}</h3><p>투자금 ${m(f.investment.amount)} · 투자사 누적 배분 ${m(f.investment.paid)} · ${K.modernFilm(f)?'회수 후 순이익 비율':'기존 정산 배분율'} ${Math.round(f.investment.share*100)}%</p><p class="small muted">${safeDate(f.investment.deadline)} 공개 기한 · ${f.investment.late?'기한 경과 가산 적용':f.releaseMonth!=null||f.ott?'공개 완료':'일정 관리 중'}</p>${A('영화 상세','open-film',f.id)}</section>`).join('')||'<p class="small muted mt-sm">아직 체결된 계약이 없습니다.</p>'}`);
 }
 function screeningView(id){
  const f=film(id);if(!f)return shell('테스트 시사회','',blank('작품을 찾을 수 없습니다.','영화 상세에서 다시 선택하세요.'));
  const x=f.screening;
  const status={running:'관객 의견을 수집 중입니다.',decision:'관객 반응을 바탕으로 후속 작업을 선택하세요.',editing:'선택한 보완 작업을 진행 중입니다.',done:'시사회와 후속 선택을 완료했습니다.'};
  let body=`<p>후반작업 70% 이후 작품당 한 번 진행합니다. 관객층별 의견은 흥행 보장이 아닌 참고 자료이며, 보완 효과도 제한적입니다.</p>`;
  if(!x){body+=`<div class="detail-metrics"><div><small>시사회 비용</small><strong>${m(B.screeningFee(f))}</strong></div><div><small>의견 도착</small><strong>1주 뒤</strong></div></div>${B.screeningAvailable(f)?A('시사회 열기','screening-start',id,'primary'):blank('지금은 시사회를 열 수 없습니다.','제작 70% 이후·미개봉 작품이며, 편집 협의와 선행 영화제 출품이 없어야 합니다.')}`;}
  else{
   body+=`<div class="notice mt"><p><strong>${status[x.status]??''}</strong>${['running','editing'].includes(x.status)?'<br>'+safeDate(x.dueWeek)+' 완료 예정':''}</p></div>`;
   if(x.status!=='running')body+=`<div class="growth-cards">${x.groups.map(g=>`<section class="card growth-card"><header class="growth-review-head"><h3>${esc(g.name)}</h3><strong>${g.score}<small>/100</small></strong></header><p>${esc(g.text)}</p></section>`).join('')}</div>`;
   if(x.status==='decision')body+=`<div class="growth-cards">${B.screeningOptions(state(),f).map(q=>`<section class="card growth-card"><h3>${q.name}</h3><p>${q.description}</p><p class="small">${m(q.cost)} · ${q.weeks}주 · 품질 ${q.quality>=0?'+':''}${q.quality}</p>${q.unavailable?'<p class="small red">제작진 일정이 겹칩니다.</p>':''}${A('이 방향으로 결정','screening-decide',id,'primary',`data-choice="${q.id}" ${q.unavailable?'disabled':''}`)}</section>`).join('')}</div>`;
   if(x.decision)body+=`<p class="mt small">선택: ${esc(x.decision.name)} · 보완비 ${m(x.decision.cost)} · ${x.status==='done'?'반영 품질 '+(x.appliedQuality??0):'진행 중'}</p>`;
  }
  return shell('테스트 시사회',esc(f.title),body);
 }
 function foreignView(id){
  const f=film(id);if(!f)return shell('해외 배급','',ownFilms().filter(f=>!f.ott&&['ready','shelved','showing','closed'].includes(f.status)).map(f=>filmRow(f,'foreign')).join('')||blank('계약 가능한 완성작이 없습니다.','글로벌 OTT 독점작은 해외에 중복 판매할 수 없습니다.'));
  if(f.ott)return shell('해외 배급',esc(f.title),blank('글로벌 OTT 독점 계약 중입니다.','해외 배급권을 따로 판매할 수 없습니다.'));
  const offers=B.foreignOffers(state(),f),ready=['ready','shelved','showing','closed'].includes(f.status);
  return shell('해외 배급 제안',esc(f.title),`<div class="notice small"><p>가상 배급사·게임용 제안입니다. 일시금은 바로 정산, 수익 배분은 8주간 변동 정산합니다. 현지화 비용은 두 방식 모두 선지출하며, 원작료·투자사 몫을 차감한 금액만 제작사가 받습니다.</p></div><div class="growth-cards">${offers.map(o=>`<section class="card growth-card ${o.sold?'is-muted':''}"><span class="eyebrow">${o.name}</span><h3>${o.company}</h3><p class="small">선호: ${o.genres.map(g=>GENRE[g]?.name??g).join(' · ')}</p><dl class="growth-values"><div><dt>자막·더빙 선지출</dt><dd>${m(o.localization)}</dd></div><div><dt>일시금 (배분 전)</dt><dd>${m(o.upfront)}</dd></div><div><dt>8주 예상 (배분 전)</dt><dd>${m(o.projected)}</dd></div></dl><div class="row wrap">${o.sold?'<span class="tag green">계약 완료</span>':`${A('일시금 계약','foreign-sign',id,'primary',`data-territory="${o.id}" data-mode="fixed" ${ready?'':'disabled'}`)}${A('수익 배분 계약','foreign-sign',id,'ghost',`data-territory="${o.id}" data-mode="share" ${ready?'':'disabled'}`)}`}</div></section>`).join('')}</div><p class="small muted">한 영화의 한 지역 판권은 한 번만 판매할 수 있습니다. 해외 계약 후 글로벌 OTT 독점 계약은 불가합니다. 국내 관객·국내 박스오피스에는 합산하지 않습니다. 선공개 약정 중에는 계약할 수 없습니다.</p>`);
 }
 function graph(rows){if(!rows.length)return '<p class="small muted">아직 해외 정산 기록이 없습니다.</p>';const values=new Map();for(const r of rows)values.set(r.week,(values.get(r.week)??0)+r.receipts);const pts=[...values].sort((a,b)=>a[0]-b[0]),max=Math.max(1,...pts.map(p=>p[1])),d=pts.map((p,i)=>`${i?'L':'M'}${32+i*516/Math.max(1,pts.length-1)},${155-p[1]/max*125}`).join(' ');return `<svg class="growth-chart" viewBox="0 0 580 195" role="img" aria-label="해외 주간 실수령 기록 그래프"><path class="growth-axis" d="M32 20V155H548"/><path class="growth-line" d="${d}"/>${pts.map((p,i)=>`<circle cx="${32+i*516/Math.max(1,pts.length-1)}" cy="${155-p[1]/max*125}" r="3"><title>${safeDate(p[0])} ${m(p[1])}</title></circle>`).join('')}<text x="32" y="184">${safeDate(pts[0][0])}</text><text x="548" y="184" text-anchor="end">${safeDate(pts.at(-1)[0])}</text><text x="36" y="18">최대 ${m(max)}</text></svg>`;}
 function foreignReport(){
  const films=ownFilms().filter(f=>f.foreignDeals?.length),runs=films.flatMap(f=>f.foreignDeals.flatMap(d=>d.runs.map(r=>({...r,title:f.title,company:d.company})))),sorted=[...runs].sort((a,b)=>b.week-a.week),size=10,pages=Math.max(1,Math.ceil(sorted.length/size)),page=Math.min(ui.growthPage??0,pages-1);
  return shell('해외 성과 · 정산','국내 관객·매출과 별도 집계합니다. 외화·환율은 시뮬레이션하지 않고 억 원으로 정산합니다.',`<div class="detail-metrics"><div><small>해외 누적 실수령</small><strong>${m(E.player(state()).totalForeignReceipts)}</strong></div><div><small>해외 판매 작품</small><strong>${films.length}편</strong></div><div><small>진행 중인 계약</small><strong>${films.flatMap(f=>f.foreignDeals).filter(d=>d.status==='active').length}건</strong></div></div>${graph(runs)}${films.map(f=>filmRow(f,'foreign','계약 보기')).join('')}<h3 class="mt">주간 실수령 기록</h3><div class="growth-ledger">${sorted.slice(page*size,(page+1)*size).map(r=>`<article><div><strong>${esc(r.title)}</strong><small>${safeDate(r.week)} · ${esc(r.company)}</small></div><b>${m(r.receipts)}</b></article>`).join('')||'<p class="small muted">첫 계약 이후 여기에 기록됩니다.</p>'}</div>${pages>1?pager(page,pages):''}`,`${back()}${A('해외 배급할 작품 선택','foreign','','primary')}`);
 }
 function seriesView(id){
  const selected=film(id),groups=B.seriesGroups(state());
  if(!selected)return shell('시리즈·세계관','속편·프리퀄·스핀오프·리부트로 이야기를 확장합니다. 팬층, 제작 간격, 출연진 변화가 첫 흥행에 제한적으로 반영됩니다.',`${groups.map(g=>`<section class="card growth-card"><h3>${esc(g.title)}</h3><p class="small">${g.films.length}편 · 가상 팬층 약 ${E.viewers(g.fans)}명 · 최근 48주 기획 ${g.recent}편</p>${g.films.map(f=>filmRow(f,'series','세계관 보기')).join('')}</section>`).join('')||blank('첫 작품부터 시작해 보세요.','공개한 작품을 바탕으로 새로운 시리즈를 기획할 수 있습니다.')}`);
  const root=selected.seriesPlan?.root??selected.seriesRoot??selected.id,g=groups.find(g=>g.root===root),published=selected.releaseMonth!=null||selected.ott;
  return shell('시리즈의 다음 이야기',esc(selected.title),`<div class="notice"><p>${g?.films.length??1}편의 세계관 · 가상 팬층 약 ${E.viewers(g?.fans??0)}명. 최근 제작이 몰리면 피로도가 높아지며 주연·감독 교체도 기대에 영향을 줍니다.</p></div><div class="growth-cards">${B.SERIES_TYPES.map(([key,name,desc])=>`<section class="card growth-card"><h3>${name}</h3><p>${desc}</p>${A('이 방향으로 기획','series-pitch',selected.id,'primary',`data-series="${key}" ${published?'':'disabled'}`)}</section>`).join('')}</div>${!published?'<p class="small muted">극장 또는 OTT에 먼저 공개해야 후속 기획을 만들 수 있습니다.</p>':''}<h3 class="mt">같은 세계관의 작품</h3>${(g?.films??[selected]).map(f=>filmRow(f,'open-film','상세')).join('')}`);
 }
 function festivalsView(id){
  const f=film(id);
  if(!f){const eligible=ownFilms().filter(f=>['ready','shelved','showing','closed','streaming'].includes(f.status));return shell('영화제 출품','기존 연말 시상식과 별도로 직접 출품하는 가상 영화제입니다. 접수는 개최 8주 전부터 가능합니다.',`<div class="growth-cards">${B.FESTIVALS.map(t=>{const q=B.festivalOpportunities(state(),null).find(x=>x.id===t.id);return `<section class="card growth-card"><h3>${t.name}</h3><p>${t.description}</p><p class="small">${safeDate(q.openWeek)} 접수 시작<br>${safeDate(q.dueWeek)} 결과 · 출품료 ${m(t.fee)}</p></section>`;}).join('')}</div><h3 class="mt">출품할 작품</h3>${eligible.map(f=>filmRow(f,'festivals','선택')).join('')||blank('아직 완성작이 없습니다.','완성한 영화의 조건을 확인하고 출품할 수 있습니다.')}`);}
  const offers=B.festivalOpportunities(state(),f);
  return shell('영화제 출품 조건',esc(f.title),`<div class="growth-cards">${offers.map(t=>`<section class="card growth-card"><h3>${t.name}</h3><p>${t.description}</p><p class="small">접수 ${safeDate(t.openWeek)}부터<br>결과 ${safeDate(t.dueWeek)} · 비용 ${m(t.fee)}</p>${t.issues.length?`<p class="small muted">${t.issues.map(issue=>esc(issue.startsWith('접수 시작')?'아직 접수 기간이 아닙니다.':issue)).join('<br>')}</p>`:''}${A('출품하기','festival-submit',id,'primary',`data-festival="${t.id}" ${t.eligible?'':'disabled'}`)}</section>`).join('')}</div><h3 class="mt">출품 이력</h3>${(f.festivalEntries??[]).map(e=>`<section class="card growth-card"><h3>${esc(e.name)}</h3><p>${{submitted:'심사 중',withdrawn:'출품 취소',selected:'공식 선정',winner:'작품상','not-selected':'미선정'}[e.status]} · ${safeDate(e.dueWeek)}</p>${e.status==='submitted'?A('출품 취소 (환불 없음)','festival-withdraw',id,'ghost',`data-key="${esc(e.key)}"`):''}</section>`).join('')||'<p class="small muted">출품 기록이 없습니다.</p>'}<p class="small muted">출품료는 반환되지 않습니다. 선공개 약정은 결과 또는 취소까지 극장·OTT·해외 배급을 제한합니다. 선정·수상은 보장하지 않습니다.</p>`);
 }
 function saveView(){
  const metadata=id=>slots.find(x=>x.id===id);
  const slot=(id,title,manual=false)=>{const x=metadata(id);return `<section class="card growth-card"><h3>${title}</h3>${x?`<p><strong>${esc(x.company)}</strong><br>${safeDate(x.week)} · 작품 ${x.films}편 · ${m(x.cash)}</p><p class="small muted">${esc(new Date(x.updatedAt).toLocaleString('ko-KR'))}</p>`:'<p class="small muted">비어 있음</p>'}<div class="row wrap">${manual?A(x?'현재 게임으로 덮어쓰기':'여기에 저장','slot-save',id,'primary',state()?'':'disabled'):''}${x?`${A('불러오기','slot-load',id,'ghost')}${A('삭제','slot-delete',id,'text-btn')}`:''}</div></section>`;};
  return shell('저장 관리','직접 저장 3개 · 최근 주간 백업 3개 · 교체 전 안전 백업 1개. 다른 기기는 JSON 파일로 옮깁니다.',`<div class="growth-storage-actions">${A('현재 게임 JSON 내보내기','export','','primary',state()?'':'disabled')}${A('JSON 파일 불러오기','import','','ghost')}${A('슬롯 새로고침','slot-refresh')}</div><p class="small muted mt-sm">이 브라우저·이 사이트에만 저장합니다. 클라우드 동기화가 아니며 사이트 데이터 삭제 시 슬롯도 사라질 수 있습니다. 중요한 진행은 파일로 보관하세요.</p>${vaultError||ui.vaultWarning?`<div class="notice warning">${esc(vaultError||ui.vaultWarning)}</div>`:''}${loadingVault?'<p role="status">저장 슬롯 확인 중…</p>':''}<h3 class="mt">직접 저장</h3><div class="growth-cards">${[1,2,3].map(i=>slot('manual-'+i,'저장 슬롯 '+i,true)).join('')}</div><details class="fold-section"><summary>최근 주간 자동 백업</summary><div class="growth-cards">${[0,1,2].map((i)=>slot('auto-'+i,'주간 백업 '+(i+1))).join('')}</div></details><details class="fold-section"><summary>게임 교체 전 안전 백업</summary>${slot('safety','이전 게임 보존')}</details>`);
 }
 function wizardTools(d){const q=E.estimate(d,state()),f=q.finance,series=B.seriesForecast(state(),d);return `<section class="growth-wizard-tools"><p class="small muted">작가·감독·배우 한 편 계약료 ${m(q.writer+q.cast)} · 총 제작비의 ${Math.round((q.writer+q.cast)/q.total*100)}%. 정산은 매출과 구분합니다.</p>${K.feeWarning(d,q)?`<p class="notice warning small">${K.feeWarning(d,q)}</p>`:''}<div class="growth-toolbar">${btn('수익 배분 기준','economy-details','','ghost small-btn')}${A('기획 저장','draft-save')}${A('제작팀 저장·불러오기','teams')}${A('투자 제안','investment')}</div>${q.facilitySavings?`<p class="small muted">시설 효과: ${q.facilitySnapshot.names.join(' · ')} · 준비비 ${m(q.facilitySavings)} 절감 · ${q.facilitySnapshot.weeks}주 단축 (계약 시 고정)</p>`:''}${f?`<p class="small ${f.eligible?'lime':'red'}">공동제작: ${esc(f.name)} · ${f.eligible?`투자 ${m(f.amount)} / 우리 부담 ${m(q.cashNeeded)}`:'조건 미충족 · 투자 제안을 다시 확인하세요.'}</p>`:''}${d.script.seriesPlan?`<p class="small muted">시리즈 기대 모형 ×${series.factor} · 팬층 ${E.viewers(series.fans)}명 · 최근 제작 피로 ${Math.round(series.fatigue*100)}% · 제작진 연속성 ${Math.round(series.continuity*100)}%</p>`:''}</section>`;}
 function filmTools(f){if(!f||f.company!=='c0')return '';return `<section class="growth-film-tools"><div class="growth-toolbar">${btn('수익 정산 내역','economy-details',`data-id="${f.id}"`,'ghost small-btn')}${A('테스트 시사회','screening',f.id)}${A('해외 배급','foreign',f.id)}${A('시리즈·세계관','series',f.id)}${A('영화제 출품','festivals',f.id)}</div>${f.investment?`<p class="small muted">${esc(f.investment.name)} 투자 ${m(f.investment.amount)} · ${K.modernFilm(f)?'비용 회수 후 순이익의':'기존 정산액의'} ${Math.round(f.investment.share*100)}% 투자사 배분 · 누적 배분 ${m(f.investment.paid)}. 작품 손익은 투자금 유입을 포함한 우리 회사의 순현금 기준입니다.</p>`:''}${f.screening?`<p class="small muted">시사회: ${{running:'의견 수집 중',decision:'후속 선택 대기',editing:'보완 중',done:'완료'}[f.screening.status]}</p>`:''}${f.foreignDeals?.length?`<p class="small muted">해외 ${f.foreignDeals.length}개 지역 판매 · ${m(f.foreignDeals.reduce((n,d)=>n+d.receipts,0))} 실수령 (국내 관객과 별도)</p>`:''}</section>`;}
 function modalMarkup(m){if(!m.type.startsWith('growth-'))return null;const t=m.type.slice(7);
  if(t==='storage')return saveView();if(t==='confirm'){const x=confirmations.get(m.id);return x?shell(x.title,'확정 전에는 비용·계약·저장 내용을 바꾸지 않습니다.',`<p>${esc(x.text)}</p>${x.detail}`,`${back()}${A(x.label,'confirm',m.id,'primary')}`):shell('이미 처리한 요청','',blank('이 확인은 만료되었습니다.','뒤로 돌아가서 현재 조건을 다시 확인하세요.'));}
  if(!state())return shell('저장된 제작사가 없습니다.','',blank('새 게임을 시작하거나 저장을 불러오세요.','저장 관리에서 JSON 파일을 가져올 수 있습니다.'),A('저장 관리','storage','','primary'));
  return {favorites:favoritesView,teams:teamView,drafts:draftsView,facilities:facilityView,investment:investmentView,screening:()=>screeningView(m.id),foreign:()=>foreignView(m.id),'foreign-report':foreignReport,series:()=>seriesView(m.id),festivals:()=>festivalsView(m.id)}[t]?.()??shell('메뉴를 찾을 수 없습니다.','','뒤로 돌아가 주세요.');
 }
 function captureDraft(immediate=false){
  clearTimeout(autoTimer);const save=()=>{const s=state(),d=ui.draft;if(!s||!d||s.films.some(f=>f.company==='c0'&&f.script.id===d.script.id))return;const old=group().drafts.find(x=>x.id==='auto-draft');if(JSON.stringify(old?.draft)===JSON.stringify(d)&&old?.step===ui.step)return;B.archiveDraft(s,d,ui.step,{automatic:true});persist();};
  if(immediate)save();else autoTimer=setTimeout(save,650);
 }
 function restoreAuto(){const g=group();if(g&&!ui.draft){const item=g.drafts.find(x=>x.id==='auto-draft');if(item){try{const x=B.restoreDraft(state(),item.id);ui.draft=x.draft;ui.step=x.step;}catch{/* Keep unavailable archived drafts, never open them automatically. */}}}}
 function prepareLoad(candidate){
  const c=E.player(candidate);ask('이 저장으로 이어서 플레이할까요?',`${c.name} · ${safeDate(E.weekOf(candidate))} · ${m(c.cash)}. 현재 게임을 안전 백업한 뒤 대시보드로 이동합니다.`,async()=>{if(state())await Vault.putSave('safety',state(),'교체 전 안전 백업');ctx.installSave(candidate);await loadSlots();},'백업 후 불러오기');
 }
 function handleAction(a,id,button){
  if(!a.startsWith('growth-'))return false;const type=a.slice(7);
  if(ui.growthBusy){toast('저장 작업을 마친 뒤 다시 선택해 주세요.');return true;}
  if(['storage','favorites','teams','drafts','facilities','investment','screening','foreign','foreign-report','series','festivals'].includes(type)){if(type==='drafts'||type==='storage')captureDraft(true);show(type,id);return true;}
  if(type==='confirm'){const x=confirmations.get(id);if(!x)return true;asyncRun(async()=>{const result=await x.run();confirmations.delete(id);persist();if(ui.modal?.type==='growth-confirm'&&ui.modal.id===id){ui.modal=x.returnTo;ui.peekStack?.pop();render();}if(result?.message)toast(result.message);});return true;}
  if(type==='page'){ui.growthPage=Math.max(0,(ui.growthPage??0)+Number(button.dataset.delta));renderDialog();return true;}
  if(type==='open-film'){features.deepOpen('film',id);return true;}
  if(type==='favorite'){const selected=B.toggleFavorite(state(),id);persist();render();toast(selected?'관심 인물로 등록했습니다.':'관심 등록을 해제했습니다.');return true;}
  if(type==='team-save'){const t=B.saveTeam(state(),ui.draft,ui.growthTeamName);persist();renderDialog();toast(t.name+' 저장 완료');return true;}
  if(type==='team-load'){const x=B.loadTeam(state(),ui.draft,id);ui.draft=x.draft;ui.step=1;ui.modal={type:'wizard'};ui.peekStack=[];captureDraft(true);render();toast(x.missing.length?'일정·활동 조건으로 제외: '+x.missing.join(', '):'제작팀을 불러왔습니다. 섭외 조건은 다시 확인합니다.');return true;}
  if(type==='draft-save'){captureDraft(true);B.archiveDraft(state(),ui.draft,ui.step);persist();if(ui.modal?.type==='growth-drafts')renderDialog();toast('기획 보관함에 별도로 저장했습니다.');return true;}
  if(type==='draft-load'){ask('보관한 기획을 열까요?','다른 기획을 편집 중이었다면 별도 보관합니다(8개 한도). 저장한 기획은 계약 조건을 다시 확인하도록 작품 기획 단계에서 열립니다.',()=>{const saved=group().drafts.find(x=>x.id===id);if(!saved)throw Error('보관한 기획이 없습니다.');if(ui.draft&&ui.draft.script.id!==saved.draft.script.id&&!group().drafts.some(x=>x.id!=='auto-draft'&&x.draft.script.id===ui.draft.script.id))B.archiveDraft(state(),ui.draft,ui.step);const x=B.restoreDraft(state(),id);ui.draft=x.draft;ui.step=x.step;ui.pendingSelection=null;ui.replacement=null;ui.picker=null;ui.peekStack=[];ui.home=false;ui.modal={type:'wizard'};captureDraft(true);render();},'이어서 편집');return true;}
  if(type==='remove'){ask('보관 기록을 삭제할까요?','선택한 보관 항목만 삭제합니다. 제작 중인 영화와 현재 게임은 바뀌지 않습니다.',()=>B.removeSaved(state(),button.dataset.kind,id),'삭제');return true;}
  if(type==='facility'){const mode=button.dataset.mode,q=B.facilityQuote(state(),id,mode);ask(`${q.name} ${mode==='own'?'구입':mode==='lease'?'임대':'운영 종료'}`,`지금 ${q.cost<0?'수령':'지출'} ${m(Math.abs(q.cost))} · 이후 월 시설비 ${m(q.monthly)}. 현재 제작 중인 영화의 계약 효과는 보존됩니다.`,()=>B.changeFacility(state(),id,mode),'계약 확정');return true;}
  if(type==='investor-select'){if(!ui.draft)throw Error('먼저 시나리오를 기획해 주세요.');if(id){const q=B.investorOffers(state(),ui.draft,E.estimate(ui.draft,state())).find(x=>x.id===id);if(!q?.eligible)throw Error('현재 기획은 이 조건을 충족하지 못합니다.');}ui.draft.investorId=id||null;captureDraft(true);renderDialog();toast(id?'투자 조건을 선택했습니다. 제작 확정 전에는 입금되지 않습니다.':'자체 제작으로 변경했습니다.');return true;}
  if(type==='screening-start'){const f=film(id);ask('테스트 시사회를 열까요?',`시사회 비용 ${m(B.screeningFee(f))}. 1주 뒤 관객 의견이 도착하며 결정 전까지 개봉·OTT·해외 배급은 보류됩니다.`,()=>B.startScreening(state(),id),'시사회 시작');return true;}
  if(type==='screening-decide'){const q=B.screeningOptions(state(),film(id)).find(x=>x.id===button.dataset.choice);if(!q)throw Error('이미 처리한 시사회입니다.');ask(q.name+' 확정',`${m(q.cost)} · ${q.weeks}주 · 예상 품질 ${q.quality>=0?'+':''}${q.quality}. ${q.description}`,()=>B.decideScreening(state(),id,q.id),'결정 전달');return true;}
  if(type==='foreign-sign'){const mode=button.dataset.mode,t=button.dataset.territory,q=B.foreignOffers(state(),film(id)).find(x=>x.id===t);ask(q.name+' 배급 계약',`현지화 비용 ${m(q.localization)} 선지출. ${mode==='fixed'?'일시금 '+m(q.upfront):'8주 예상 '+m(q.projected)+' (실제 정산 변동)'}에서 원작료와 투자사 몫을 차감합니다. 계약 이후 글로벌 OTT 독점 판매는 불가합니다.`,()=>B.signForeign(state(),id,t,mode),'배급 계약 확정');return true;}
  if(type==='series-pitch'){const series=button.dataset.series;ask('새 시리즈 기획',`${esc(film(id).title)}의 ${B.SERIES_TYPES.find(x=>x[0]===series)?.[1]} 제안을 받습니다. 새 배우·감독을 선정하며 돈은 제작 확정 때만 지출됩니다.`,()=>{const p=B.createSeriesPitch(state(),id,series);captureDraft(true);ctx.startPlanning(p.id);ui.peekStack=[];renderDialog();},'기획 열기');return true;}
  if(type==='festival-submit'){const t=button.dataset.festival,q=B.festivalOpportunities(state(),film(id)).find(x=>x.id===t);ask(q.name+' 출품',`출품료 ${m(q.fee)} (환불 없음). 결과 ${safeDate(q.dueWeek)}. ${q.premiere?'결과 전까지 다른 경로의 선공개는 제한됩니다.':'선공개 제한은 없습니다.'} 선정과 수상은 보장하지 않습니다.`,()=>B.submitFestival(state(),id,t),'출품 확정');return true;}
  if(type==='festival-withdraw'){ask('출품을 취소할까요?','출품료는 돌려받지 못하지만 해당 영화제의 선공개 약정은 해제됩니다.',()=>B.withdrawFestival(state(),id,button.dataset.key),'취소 확정');return true;}
  if(type==='slot-refresh'){loadSlots();return true;}
  if(type==='slot-save'){captureDraft(true);ask('저장 슬롯에 기록할까요?','이 슬롯의 기존 기록만 교체됩니다. 다른 슬롯과 현재 게임은 유지됩니다.',async()=>{await Vault.putSave(id,state());await loadSlots();toast('슬롯 저장을 완료했습니다.');},'저장');return true;}
  if(type==='slot-load'){asyncRun(async()=>prepareLoad(await Vault.getSave(id)));return true;}
  if(type==='slot-delete'){ask('이 저장 슬롯을 삭제할까요?','선택한 슬롯만 삭제하며 현재 플레이 중인 게임은 바꾸지 않습니다.',async()=>{await Vault.deleteSave(id);await loadSlots();},'삭제');return true;}
  if(type==='export'){captureDraft(true);const json=JSON.stringify(Vault.exportSave(state())),url=URL.createObjectURL(new Blob([json],{type:'application/json'})),a=document.createElement('a');a.href=url;a.download=`lasttake-${E.weekOf(state())+1}week-save.json`;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),60000);toast('저장 파일 내보내기를 요청했습니다.');return true;}
  if(type==='import'){const input=document.createElement('input');input.type='file';input.accept='.json,application/json';input.hidden=true;document.body.append(input);input.oncancel=()=>input.remove();input.onchange=()=>asyncRun(async()=>{try{const f=input.files?.[0];if(!f)return;if(f.size>32*1024*1024)throw Error('32MB 이하의 JSON 파일을 선택해 주세요.');pendingImport=Vault.parseSave(await f.text());prepareLoad(pendingImport);}finally{input.remove();}});input.click();return true;}
  return true;
 }
 function handleField(event){const key=event.target.dataset.growth;if(!key)return false;if(key==='teamName')ui.growthTeamName=event.target.value;return true;}
 return {toolbar,favoriteControl,wrapPerson,favoritesButton,wizardTools,filmTools,modalMarkup,handleAction,handleField,captureDraft,restoreAuto};
}
